import { z } from 'zod';
import {
  TELEMETRY_EVENT_NAMES,
  TELEMETRY_LANGUAGES,
  TELEMETRY_PLATFORMS,
} from '../models/telemetry-event.model';

/** Random install id generated by the app (UUID v4 / v7 shaped). */
const installId = z
  .string()
  .regex(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i);

/** Reports are small and bounded; anything else is rejected, not trimmed. */
export const MAX_EVENTS_PER_REQUEST = 25;

export const telemetryBatchSchema = z
  .object({
    installId,
    appVersion: z
      .string()
      .regex(/^[0-9A-Za-z.+-]{1,20}$/, 'Invalid appVersion'),
    platform: z.enum(TELEMETRY_PLATFORMS),
    lang: z.enum(TELEMETRY_LANGUAGES),
    events: z
      .array(
        z
          .object({
            name: z.enum(TELEMETRY_EVENT_NAMES),
            /** Client timestamp (epoch milliseconds), optional. */
            ts: z.number().int().positive().optional(),
          })
          .strict()
      )
      .min(1)
      .max(MAX_EVENTS_PER_REQUEST),
  })
  // Unknown keys (for example a stray user id) are rejected rather than stored.
  .strict();

export type TelemetryBatchInput = z.infer<typeof telemetryBatchSchema>;

export const telemetryDeleteSchema = z.object({ installId }).strict();

export const telemetrySummaryQuerySchema = z
  .object({
    days: z.coerce.number().int().min(1).max(90).default(30),
  })
  .strict();
